'use strict';
const UI4={bind,render,liveView,drawReplay4,startReplay4,help,hqView,peopleView,boardView,report};
let designState5=state;
let designStore=state.stores[0]?.id||null,floorDraft=null,designSelected='counter',liveDay5=0;
function currentDesign5(){const s=state.stores.find(s=>s.id===designStore)||state.stores[0];designStore=s.id;if(!floorDraft||floorDraft.store!==s.id)floorDraft={store:s.id,floor:JSON.parse(JSON.stringify(s.floor))};return s;}
function floorSvg5(floor,options={}){const active=options.active,frame=options.frame,items=floor.items,occupied=frame?.occupied||0;return `<svg class="floor-plan5" viewBox="0 0 696 412" role="img" aria-label="Půdorys kavárny, stanice, průchozí uličky a stoly"><rect x="5" y="5" width="686" height="402" rx="10" fill="#f0eee3" stroke="#adb7a1" stroke-width="3"/>${Array.from({length:48},(_,i)=>{const x=i%8,y=Math.floor(i/8);return `<rect x="${12+x*84}" y="${12+y*65}" width="82" height="63" fill="${(x+y)%2?'#e8e6d8':'#efedde'}" stroke="#d9ddcd" stroke-width="1" ${options.edit?`class="floor-cell5" data-floor-cell="${x},${y}" tabindex="0" role="button" aria-label="Umístit vybraný prvek: sloupec ${x+1}, řada ${y+1}"`:''}/>`}).join('')}${items.map((item,i)=>{const cfg=STATIONS5[item.kind],isTable=!!cfg.seats,used=isTable?Math.min(cfg.seats,Math.max(0,occupied-items.filter((x,j)=>j<i).reduce((a,x)=>a+(STATIONS5[x.kind].seats||0),0))):0;return `<g ${options.edit?`class="floor-item5" data-floor-select="${item.id}" tabindex="0" role="button" aria-label="Vybrat ${esc(cfg.name)}"`:''}><rect x="${17+item.x*84}" y="${17+item.y*65}" width="${cfg.w*84-12}" height="${cfg.h*65-12}" rx="${item.kind==='table2'?18:item.kind==='barseat'?3:7}" fill="${isTable?'#c7ad7d':item.kind==='counter'||item.kind==='pickup'?'#264b3b':'#d0daca'}" stroke="${item.id===active?'#bd7643':'#86947e'}" stroke-width="${item.id===active?4:1}"/><text x="${23+item.x*84}" y="${39+item.y*65}" font-size="11" fill="${['counter','pickup'].includes(item.kind)?'#fffdf8':'#263d34'}">${esc(item.kind==='table2'?'Stolek':item.kind==='barseat'?'Bar':cfg.name.replace(' · 4 místa',''))}</text>${isTable?`<text x="${23+item.x*84}" y="${57+item.y*65}" font-size="10" fill="#263d34">${used} / ${cfg.seats} hosté</text>`:''}</g>`}).join('')}<text x="22" y="${12+5*65+53}" font-size="11" fill="#264b3b" font-weight="700">VCHOD</text><text x="${17+7*84}" y="${12+5*65+53}" font-size="11" fill="#264b3b" font-weight="700">VÝCHOD</text>${frame?`<g><rect x="14" y="14" width="190" height="49" rx="6" fill="#fffdf8" opacity=".96"/><text x="25" y="34" font-size="12" fill="#264b3b">Fronta: ${frame.queue} · směna: ${frame.workers}</text><text x="25" y="52" font-size="11" fill="#6c755f">${frame.fault?'Porucha kávovaru · omezený výkon':'Výdej: '+frame.served+' hostů za 10 min'}</text></g>`:''}</svg>`}
function interiorView(){const s=currentDesign5();let info,error='';try{info=floorInfo5(floorDraft.floor,s.seats)}catch(e){error=e.message}const owner=owner5(s);return `<div class="view-toolbar"><p class="intro">Vyber stanici a potom volné políčko. Přesuny se projeví po potvrzení přestavby. Rozpis určuje počet lidí v každé části dne.</p>${field('Kavárna',`<select id="designStore5">${storeOptions(s.id)}</select>`)}</div><div class="live-layout"><section class="card"><div class="card-head"><h2>Pracovní půdorys</h2><span class="badge">8 × 6 polí</span></div>${floorSvg5(floorDraft.floor,{edit:true,active:designSelected})}<div class="fields">${field('Vybraný prvek',`<select id="designSelected5">${floorDraft.floor.items.map(i=>option(i.id,STATIONS5[i.kind].name+' · '+i.id,designSelected)).join('')}</select>`)}<div class="actions"><button class="soft" id="addTable5">Přidat stůl</button><button class="soft" id="removeTable5" ${floorDraft.floor.items.find(i=>i.id===designSelected)?.kind!=='table'?'disabled':''}>Odebrat stůl</button></div></div>${error?`<div class="warning">${esc(error)}</div>`:rows([['Vliv pohybu na výkon',number(info.flow*100,1)+' %'],['Přístupná místa',info.seats+' / '+s.seats],['Pohyb při přípravě',info.work+' polí mezi stanicemi']])}<div class="actions"><button class="primary" id="applyFloor5" ${error||s.franchise||JSON.stringify(s.floor)===JSON.stringify(floorDraft.floor)?'disabled':''}>Potvrdit přestavbu · 25 000 Kč</button><button class="soft" id="resetFloorDraft5">Vrátit změny</button>${s.equipment.window&&!floorDraft.floor.items.some(i=>i.kind==='window')?'<button class="soft" id="addWindow5">Umístit okénko</button>':''}</div><p class="sub">Vchod, východ a přístup ke každé stanici musí zůstat průchozí. Stůl má čtyři místa; celkový počet je omezen kapacitou kavárny. Nevyužitá místa doplníš stoly, další kapacitu pořídíš v Menu & vybavení.</p></section><div class="stack"><section class="card"><h2>Směny · šest dnů týdně</h2><div class="fields">${s.daily.shifts.map((n,i)=>field(PERIODS5[i],input('shiftCount5-'+i,n,0,7))).join('')}</div><p class="sub">Tým může kombinovat plné a částečné úvazky. Stejný součet směn má stejnou cenu. Počet lidí mění kapacitu každých deset minut; přesun lidí do špičky zkrátí frontu.</p>${rows([['Týdenní mzdy baristů',money(shiftWages5(s))],['Dnešní odpovědná osoba',esc(owner?.person.name||'Zakladatel')],['Rozložení místní poptávky',SEGMENTS[loc(s.id).segment].name]])}<button class="primary wide" id="saveShifts5" ${s.franchise?'disabled':''}>Uložit ruční rozpis</button><button class="soft wide" id="suggestShifts5" ${s.franchise?'disabled':''}>Navrhnout podle špičky</button><label class="checkbox-line"><input id="shiftAuto5" type="checkbox" ${s.daily.auto?'checked':''}> Dovolit odpovědné osobě upravovat směny</label>${field('Odpovědnost za směny',`<select id="shiftOwner5">${option('manager','Vedoucí kavárny',s.daily.owner)}${option('region','Oblastní ředitel',s.daily.owner)}${option('operations','Provozní ředitel',s.daily.owner)}</select>`)}<p class="sub">Ruční rozpis vypne automatické počty lidí. Opětovné povolení vrátí vedení i pravomoc plánovat velikost týmu. Provozní ředitel potřebuje navíc aktivní mandát pro směny.</p></section><section class="card"><h3>Prověř změnu před investicí</h3><p class="sub">Plánovač používá i denní fronty, půdorys, rozpis a pravomoci vedení. Přestavbu nejprve potvrď nebo si exportuj zálohu firmy.</p><button class="soft" data-goto="live">Průběh minulého týdne</button><button class="quiet" data-goto="organization">Organizace a mandáty</button></section></div></div>`}
function profileChart5(s){const weights=HOURS5[loc(s.id).segment];return `<div class="arrival-profile5" role="img" aria-label="Očekávaná návštěvnost po hodinách">${weights.map((n,i)=>`<div><i style="height:${n/Math.max(...weights)*55}px"></i><small>${i+7}</small></div>`).join('')}</div>`}
function liveView(){const s=state.stores.find(s=>s.id===liveStore)||state.stores[0];liveStore=s.id;const report=s.daily.last,p=replayDay5(s.id,liveDay5,Math.min(71,liveFrame)),d=report?.days[liveDay5];return `<div class="view-toolbar"><p class="intro">Prodej tohoto týdne vznikl z denních front, směn, půdorysu a zásob. Přehrávka ukazuje uložené desetiminutové výsledky a neposouvá hru.</p>${field('Kavárna',`<select id="liveStore4">${storeOptions(s.id)}</select>`)}</div><div class="live-layout"><section class="card live-card"><div class="fields">${field('Den',`<select id="liveDay5">${DAYS5.map((name,i)=>option(i,name,liveDay5)).join('')}</select>`)}${field('Čas provozu',`<input id="liveSlot5" type="range" min="0" max="71" value="${Math.min(71,liveFrame)}" aria-label="Čas provozu">`)}</div><div id="dayFloor5">${floorSvg5(report?.floorSnapshot||s.floor,{frame:p})}</div><div class="scene-hud" id="dayHud5">${dayHud5(p)}</div><div class="actions"><button class="primary" id="replayToggle4">${replayPaused?'Spustit':'Pozastavit'} přehrávku</button><button class="soft" id="replayStep5">Dalších 10 minut</button><button class="soft" id="replayReset4">Od 7:00</button></div>${report?`<div class="day-chart5" id="dayChart5">${dayChart5(d,Math.min(71,liveFrame))}</div>`:'<p class="empty">Odehraj týden, aby se zaznamenal skutečný průběh provozu.</p>'}<p class="sub">Fronta, poruchy a obsazenost jsou výsledek simulace po skupinách hostů. Ve skladovém nedostatku se dostupná káva rozděluje mezi provozní intervaly. Zobrazení reportu nic znovu neúčtuje.</p></section><section class="card"><span class="eyelabel">${report?'TÝDEN '+report.week+' · '+DAYS5[liveDay5].toUpperCase():'PRVNÍ PROVOZNÍ TÝDEN ČEKÁ'}</span><h2>${loc(s.id).name}</h2>${d?rows([['Příchody hostů',d.arrivals],['Obslouženo',d.served],['Odchod kvůli frontě',d.lostQueue],['Nedostatek míst',d.lostSeats],['Příchod před zavřením',d.lostClosing],['Nedostatek kávy',d.lostStock],['Průměrné čekání',number(d.wait,1)+' min'],['Denní tržby',money(d.revenue)],['Odpovědnost provozu',esc(report.owner)]]):'<p class="sub">Příchody se mění podle typu lokality. Rozpis a půdorys nastavíš vedle.</p>'}<h3 style="margin-top:20px">Místní špička</h3>${profileChart5(s)}<div class="actions"><button class="soft" data-goto="interior">Upravit interiér a směny</button><button class="soft" data-goto="organization">Vedení provozu</button></div></section></div>`}
function clockTime5(hour){const total=round(hour*60);return Math.floor(total/60)+':'+String(total%60).padStart(2,'0')}
function dayHud5(p){return p?`<span>Čas <strong>${clockTime5(p.hour)}</strong></span><span>Fronta <strong>${p.queue}</strong></span><span>Obsazeno <strong>${p.occupied}</strong></span><span>Obsluha <strong>${p.served}</strong></span>`:'<span>Provoz čeká na první tah</span>'}
function dayChart5(d,slot){const max=Math.max(1,...d.timeline.map(p=>Math.max(p.arrivals,p.served,p.queue)));return `<div class="day-bars5" role="img" aria-label="Příchody, obsluha a fronta od 7 do 19 hodin">${d.timeline.map(p=>`<button class="day-bar5 ${p.slot===slot?'active':''}" data-day-slot="${p.slot}" aria-label="${clockTime5(p.hour)}, příchody ${p.arrivals}, obsluha ${p.served}, fronta ${p.queue}" title="${clockTime5(p.hour)} · ${p.arrivals} příchody / ${p.served} obsluha / ${p.queue} fronta"><i style="height:${p.arrivals/max*65}px"></i><b style="height:${p.served/max*65}px"></b><em style="bottom:${p.queue/max*65}px"></em></button>`).join('')}</div><div class="day-legend5"><span>Příchody</span><span>Obsloužení</span><span>Fronta</span><span>7:00–19:00</span></div>`}
drawReplay4=function(){if(view!=='live')return;const s=state.stores.find(s=>s.id===liveStore);if(!s||!el('dayFloor5'))return;const p=replayDay5(s.id,liveDay5,Math.min(71,liveFrame));el('dayFloor5').innerHTML=floorSvg5(s.daily.last?.floorSnapshot||s.floor,{frame:p});el('dayHud5').innerHTML=dayHud5(p);el('liveSlot5').value=Math.min(71,liveFrame);document.querySelectorAll('[data-day-slot]').forEach(b=>b.classList.toggle('active',Number(b.dataset.daySlot)===liveFrame));};
startReplay4=function(){stopReplay4();if(replayPaused||view!=='live')return;replayTimer=window.setInterval(()=>{if(view!=='live'){stopReplay4();return}liveFrame=(liveFrame+1)%72;drawReplay4()},450)};
function organizationView(){const o=state.organization;return `<section class="card org-tree5"><div class="card-head"><div><span class="eyelabel">OD BOARDU K VÝDEJI KÁVY</span><h2>Každý zásah má odpovědnou osobu.</h2></div><span class="badge">${usedSeats()} / ${officeSeats()||'—'} míst v kancelářích</span></div><div class="org-root5">Zakladatel · board</div><div class="org-branches5">${Object.entries(ROLES5).map(([key,c])=>`<div><strong>${c.name}</strong><span>${esc(o.executives[key].manager?.name||'Neobsazeno')}</span><small>${key==='operations'?state.regions.length+' oblastní ředitelé':state.departments[key]+' lidé v oddělení'}</small></div>`).join('')}</div><p class="sub">Ředitel obsazuje vlastní místo a má mzdu navíc k oddělení. Regionální vedení a vedoucí kaváren zůstávají konkrétní lidé. Mandát můžeš kdykoliv změnit nebo vypnout.</p></section><div class="cards">${Object.entries(ROLES5).map(([key,c])=>{const e=o.executives[key],p=o.policies[key],r=o.reports.find(r=>r.role===key);return `<section class="card executive-card5"><div class="card-head"><h3>${c.name}</h3><span class="badge">${p.enabled?'Mandát aktivní':'Ruční řízení'}</span></div><p class="sub">${c.action}</p>${e.manager?rows([['Vedení',esc(e.manager.name)],['Zaměření',e.manager.strength[c.focus]+'/100'],['Týdenní mzda',money(e.manager.salary*1.35)],['Spokojenost',round(e.manager.satisfaction)+'/100']]):'<p class="empty sub">Vyber kandidáta z trhu práce. Oddělení potřebuje alespoň jednoho pracovníka; provozní ředitel tři kavárny.</p>'}<div class="actions"><button class="soft" data-executive-hire="${key}">${e.manager?'Vyměnit ředitele':'Obsadit roli'} · 20 000 Kč</button>${e.manager?`<button class="quiet" data-executive-fire="${key}">Odvolat</button>`:''}</div><div class="fields">${field('Limit zásahu / týden (Kč)',`<input type="number" min="0" max="100000" step="1000" value="${p.budget}" data-mandate-role="${key}" data-mandate-key="budget">`)}${field('Zachovat rezervu (týdny)',`<input type="number" min="1" max="8" value="${p.reserve}" data-mandate-role="${key}" data-mandate-key="reserve">`)}</div><label class="checkbox-line"><input type="checkbox" data-mandate-role="${key}" data-mandate-key="enabled" ${p.enabled?'checked':''}> Povolit uvedené automatické zásahy</label>${key==='operations'?`<label class="checkbox-line"><input type="checkbox" data-mandate-role="${key}" data-mandate-key="maintenance" ${p.maintenance?'checked':''}> Servis přidělených kaváren</label><label class="checkbox-line"><input type="checkbox" data-mandate-role="${key}" data-mandate-key="staffing" ${p.staffing?'checked':''}> Rozložení povolených směn</label>`:''}<p class="sub">${key==='operations'?'Přiřaď kavárny řediteli v Interiéru & směnách. Ruční rozpis chrání vypnutá automatika.':key==='finance'?'Limit zahrnuje skutečně splácenou jistinu. Splácení mění dluh a hotovost.':key==='it'?'Novému projektu přidělí 8 000 Kč týdně, pokud je limit a rezerva dostatečná. Již schválený rozpočet uvidíš v centrále.':'Bez platné role, rozpočtu nebo rezervy se zásah odloží.'}</p>${r?`<div class="mandate-result5 ${r.status==='done'?'done':''}"><strong>Týden ${r.week} · ${r.status==='done'?'Provedeno':'Odloženo / bez zásahu'}</strong><p>${esc(r.text)}</p><small>Schválený výdaj ${money(r.cost)}${r.resultProfit!==undefined?' · výsledek firmy '+money(r.resultProfit):''}</small></div>`:''}</section>`}).join('')}</div><section class="card" style="margin-top:24px"><h2>Odpovědnost jednotlivých kaváren</h2>${rows(state.stores.map(s=>[loc(s.id).city+' · '+loc(s.id).name,esc(owner5(s)?.person.name||'Zakladatel')+' · '+(owner5(s)?.label||'volná role')]))}<button class="soft" data-goto="interior">Přidělit směny a pravomoci</button></section><section class="card" style="margin-top:24px"><h2>Historie zásahů vedení</h2>${o.history.length?o.history.slice(0,12).map(r=>`<div class="news"><span class="news-icon">${r.week}</span><div><strong>${ROLES5[r.role].name} · ${esc(r.name)}</strong><small>${esc(r.text)} · ${money(r.cost)}</small></div></div>`).join(''):'<p class="empty sub">Po povolení mandátů a odehrání týdne se objeví provedené zásahy.</p>'}</section>`}
function executiveDialog5(role){show(`<h2>${ROLES5[role].name}</h2><p>Nábor stojí 20 000 Kč. Ředitelská mzda je 135 % základní mzdy kandidáta. Identita, dovednosti a zkušenosti zůstávají zachované.</p>${state.talents.map(p=>`<div class="vote"><span class="avatar">${esc(p.initials)}</span><div style="flex:1"><strong>${esc(p.name)}</strong><small>${p.strength[ROLES5[role].focus]}/100 · ${money(p.salary*1.35)}/týden</small></div><button class="soft" data-executive-candidate="${p.pid}">Najmout</button></div>`).join('')||'<p>Na trhu práce nyní není dostupný kandidát.</p>'}`);on('[data-executive-candidate]',b=>{try{hireExecutive5(role,b.dataset.executiveCandidate);persist();render();el('modal').close();toast('Ředitel nastoupil.')}catch(e){toast(e.message)}})}
boardView=function(){return `<section class="card" style="margin-bottom:24px"><h3>Odpovědnost centrály</h3>${rows(state.organization.reports.map(r=>[ROLES5[r.role].name+' · '+esc(r.name),r.status==='done'?'Proveden zásah za '+money(r.cost):'Odloženo / bez zásahu']))}<button class="soft" data-goto="organization">Mandáty a důvody rozhodnutí</button></section>`+UI4.boardView()};
hqView=function(){return `<section class="card" style="margin-bottom:24px"><h3>Vedení oddělení</h3><p class="sub">${Object.values(state.organization.executives).filter(e=>e.manager).length} ředitelů · mzdy ${money(executiveCost5())}/týden. Rozpočty a rozhodnutí najdeš v Organizaci firmy.</p><button class="soft" data-goto="organization">Obsadit vedení a nastavit mandáty</button></section>`+UI4.hqView()};
report=function(id){UI4.report(id);const s=state.stores.find(s=>s.id===id);if(s.daily.last){const p=document.createElement('p');p.textContent='Průběh dne: fronta '+s.daily.last.lostQueue+' ztracených hostů, místa '+s.daily.last.lostSeats+', zavírání '+s.daily.last.lostClosing+', zásoby '+s.daily.last.lostStock+'. Odpovědnost: '+s.daily.last.owner+'.';el('modalContent').append(p)}};
bind=function(){UI4.bind();if(el('designStore5'))el('designStore5').onchange=()=>{designStore=el('designStore5').value;floorDraft=null;render()};if(el('designSelected5'))el('designSelected5').onchange=()=>{designSelected=el('designSelected5').value;render()};on('[data-floor-select]',b=>{designSelected=b.dataset.floorSelect;render()});on('[data-floor-cell]',b=>{const s=currentDesign5(),item=floorDraft.floor.items.find(i=>i.id===designSelected),[x,y]=b.dataset.floorCell.split(',').map(Number);if(!item)return;item.x=x;item.y=y;render()});document.querySelectorAll('[data-floor-cell],[data-floor-select]').forEach(node=>node.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();node.dispatchEvent(new MouseEvent('click',{bubbles:true}))}}));
 const add=kind=>{const s=currentDesign5();let added=false;for(let y=0;y<6&&!added;y++)for(let x=0;x<8&&!added;x++){const candidate={...floorDraft.floor,items:[...floorDraft.floor.items,{id:kind+'-'+(Date.now()).toString(36),kind,x,y}]};try{floorInfo5(candidate,s.seats);floorDraft.floor=candidate;designSelected=candidate.items.at(-1).id;added=true;}catch{}}if(!added)toast('V půdorysu není průchozí místo pro další prvek.');render()};if(el('addTable5'))el('addTable5').onclick=()=>add('table');if(el('addWindow5'))el('addWindow5').onclick=()=>add('window');if(el('removeTable5'))el('removeTable5').onclick=()=>{floorDraft.floor.items=floorDraft.floor.items.filter(i=>i.id!==designSelected||i.kind!=='table');designSelected='counter';render()};if(el('applyFloor5'))el('applyFloor5').onclick=()=>confirmAction('Potvrdit přestavbu?','Přesuny a změny stolů stojí celkem 25 000 Kč. Příští týden použije nový půdorys.',()=>applyFloor5(designStore,floorDraft.floor),'Přestavět');if(el('resetFloorDraft5'))el('resetFloorDraft5').onclick=()=>{floorDraft=null;render()};if(el('saveShifts5'))el('saveShifts5').onclick=()=>act(()=>setShifts5(designStore,[0,1,2].map(i=>Number(el('shiftCount5-'+i).value))),'Rozpis uložen.');if(el('suggestShifts5'))el('suggestShifts5').onclick=()=>{const counts=suggestShifts5(currentDesign5());counts.forEach((n,i)=>el('shiftCount5-'+i).value=n);toast('Návrh připravený. Uložením rozpisu ho použiješ.');};if(el('shiftAuto5'))el('shiftAuto5').onchange=()=>act(()=>{guard();const s=currentDesign5();s.daily.auto=el('shiftAuto5').checked;s.auto.staff=s.daily.auto},'Pravomoc plánovat směny upravena.');if(el('shiftOwner5'))el('shiftOwner5').onchange=()=>act(()=>setOwner5(designStore,el('shiftOwner5').value),'Odpovědnost přiřazena.');
 if(el('liveDay5'))el('liveDay5').onchange=()=>{liveDay5=Number(el('liveDay5').value);liveFrame=0;render()};if(el('liveSlot5'))el('liveSlot5').oninput=()=>{replayPaused=true;stopReplay4();liveFrame=Number(el('liveSlot5').value);el('replayToggle4').textContent='Spustit přehrávku';drawReplay4()};if(el('replayStep5'))el('replayStep5').onclick=()=>{replayPaused=true;liveFrame=(liveFrame+1)%72;render()};on('[data-day-slot]',b=>{replayPaused=true;liveFrame=Number(b.dataset.daySlot);render()});on('[data-executive-hire]',b=>executiveDialog5(b.dataset.executiveHire));on('[data-executive-fire]',b=>act(()=>fireExecutive5(b.dataset.executiveFire),'Ředitel odvolán.'));on('[data-mandate-role]',b=>act(()=>{const role=b.dataset.mandateRole,p={...state.organization.policies[role]},key=b.dataset.mandateKey;p[key]=b.type==='checkbox'?b.checked:Number(b.value);setMandate5(role,p)},'Mandát uložen.'),'change');};
help=function(){UI4.help();el('modalContent').querySelector('.eyelabel').textContent='KAVÁRNA · EDICE 05';const p=document.createElement('p');p.innerHTML='<strong>Provoz a vedení:</strong> Každý týden se počítá šest dnů od 7 do 19 hodin po desetiminutových intervalech. Hosté čekají ve frontě nebo na místo. Přesuny stanic, rozpis směn a zásoby mění skutečný počet obsloužených. V Interiéru vyber prvek a políčko, potom potvrď přestavbu. Ruční směny chrání vypnutá automatika. V Organizaci obsadíš ředitele, nastavíš limit i rezervu a uvidíš, co udělal nebo proč zásah odložil. Ředitelé potřebují místa v kanceláři a pobírají vlastní mzdu.';el('modalContent').querySelector('h2').after(p)};
render=function(){if(designState5!==state){designState5=state;floorDraft=null;designSelected='counter';liveFrame=0;}UI4.render()};
el('help').onclick=help;
render();
